    font-size: 15px;
    line-height: 1.6;
    color: #323130;
}

.email-body p {
    margin-bottom: 16px;
}

.email-body strong {
    font-weight: 600;
    color: #000000;
}

/* Configuration Section */
.config-section {
    background: #f8f8f8;
    border-left: 4px solid #0078d4;
    padding: 20px 24px;
    margin: 24px 0;
    font-family: "Consolas", "Courier New", monospace;
    font-size: 13px;
    line-height: 1.8;
    color: #323130;
    white-space: pre-wrap;
    word-wrap: break-word;
}

/* Deadline Warning */
.deadline-warning {
    background: #fef6f6;
    border-left: 4px solid #d13438;
    padding: 16px 20px;
    padding-bottom: 30px;
    margin: 24px 0;
    color: #d13438;
    font-weight: 600;
    font-size: 14px;
}

.deadline-warning strong {
    font-weight: 700;
}

/* Signature */
.signature {
    margin-top: 40px;
    padding-top: 24px;
    border-top: 1px solid #edebe9;
    color: #605e5c;
    font-size: 13px;
    line-height: 1.6;
}

.signature strong {
    color: #323130;
    font-weight: 600;
}

body {
